use std :: path :: Path ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Strips surrounding single or double quotes that some terminals add"] # [doc = " when dragging files with spaces in their names."] fn strip_surrounding_quotes (s : & str) -> & str { if s . len () < 2 { return s ; } if (s . starts_with ('\'') && s . ends_with ('\'')) || (s . starts_with ('"') && s . ends_with ('"')) { s . get (1 .. s . len () . saturating_sub (1)) . unwrap_or (s) } else { s } }